import tkinter as tk
import math

class SecondOrderCurvesFrame:

 def __init__(self, parent, status_widget, toolbar):
 self.parent = parent
 self.status = status_widget
 self.main_toolbar = toolbar

 self.frame = tk.Frame(parent)
 self.canvas_normal = None
 self.canvas_debug = None
 self.toolbar_frame = None
 self.current_curve = "circle"

 self._create_widgets()

 def _create_widgets(self):
 self.frame = tk.Frame(self.parent)

 self.canvas_normal = CurveCanvas(self.frame, is_debug=False, bg="white")
 self.canvas_normal.pack(side=tk.LEFT, fill=tk.BOTH, expand=True)

 self.canvas_debug = CurveCanvas(self.frame, is_debug=True, bg="white")
 self.canvas_debug.pack(side=tk.RIGHT, fill=tk.BOTH, expand=True)

 def _create_toolbar(self):
 for widget in self.main_toolbar.winfo_children():
 if isinstance(widget, tk.Frame) and widget != self.main_toolbar.winfo_children()[0]:
 widget.pack_forget()

 self.toolbar_frame = tk.Frame(self.main_toolbar)
 self.toolbar_frame.pack(side=tk.LEFT, padx=5)
 tk.Label(self.toolbar_frame, text="Кривая:").pack(side=tk.LEFT, padx=2)

 self.curve_var = tk.StringVar(value=self.current_curve)
 curves = [("Окружность", "circle"), ("Эллипс", "ellipse"),
 ("Гипербола", "hyperbola"), ("Парабола", "parabola")]

 for text, value in curves:
 tk.Radiobutton(self.toolbar_frame, text=text, variable=self.curve_var,
 value=value, command=lambda v=value: self._set_curve(v)).pack(side=tk.LEFT, padx=2)

 tk.Button(self.toolbar_frame, text="Очистить",
 command=self.clear).pack(side=tk.LEFT, padx=10)
 tk.Button(self.toolbar_frame, text="Сетка Вкл/Выкл",
 command=self.toggle_grid).pack(side=tk.LEFT, padx=2)

 def _set_curve(self, curve):
 self.current_curve = curve
 if self.canvas_normal:
 self.canvas_normal.set_curve(curve)
 self.canvas_debug.set_curve(curve)

 curve_names = {
 "circle": "Окружность",
 "ellipse": "Эллипс",
 "hyperbola": "Гипербола",
 "parabola": "Парабола"
 }
 self.status.config(text=f"Выбрана кривая: {curve_names.get(curve, curve)}")

 def clear(self):
 if self.canvas_normal:
 self.canvas_normal.clear()
 self.canvas_debug.clear()

 def toggle_grid(self):
 if self.canvas_debug:
 self.canvas_debug.toggle_grid()

 def show(self, curve_type="circle"):
 self.frame.pack(fill=tk.BOTH, expand=True)
 self._create_toolbar()
 self._set_curve(curve_type)
 self.status.config(text=f"Активна кривая: {curve_type}.")

 def hide(self):
 self.frame.pack_forget()
 if self.toolbar_frame:
 self.toolbar_frame.pack_forget()

class CurveCanvas(tk.Canvas):

 def __init__(self, parent, is_debug=False, **kwargs):
 super().__init__(parent, **kwargs)
 self.is_debug = is_debug
 self.cell_size = 5 if is_debug else 1
 self.grid_on = is_debug
 self.current_curve = "circle"
 self.shapes = []
 self.grid_lines = []
 self.current_points = []

 self.line_color = "black"

 if self.is_debug and self.grid_on:
 self.show_grid()

 self.bind("<Button-1>", self.start_drawing)
 self.bind("<B1-Motion>", self.draw_shape)
 self.bind("<ButtonRelease-1>", self.finish_drawing)

 self.start_x = None
 self.start_y = None

 self.bind("<Configure>", self._on_configure)

 def _snap_to_grid(self, x, y):
 x = round(x / self.cell_size) * self.cell_size
 y = round(y / self.cell_size) * self.cell_size
 return x, y

 def _get_grid_cell_coords(self, x, y):
 grid_x = (x // self.cell_size) * self.cell_size
 grid_y = (y // self.cell_size) * self.cell_size
 return grid_x, grid_y, grid_x + self.cell_size, grid_y + self.cell_size

 def _on_configure(self, event):
 if self.is_debug and self.grid_on:
 self.show_grid()
 self.redraw_shapes()

 def show_grid(self):
 self.grid_on = True

 for line in self.grid_lines:
 self.delete(line)
 self.grid_lines = []

 width = self.winfo_width()
 height = self.winfo_height()

 if width <= 1 or height <= 1:
 return

 grid_spacing = self.cell_size

 for x in range(0, width, grid_spacing):
 line = self.create_line(x, 0, x, height, fill="lightgray", dash=(2, 2), tags="grid")
 self.grid_lines.append(line)

 for y in range(0, height, grid_spacing):
 line = self.create_line(0, y, width, y, fill="lightgray", dash=(2, 2), tags="grid")
 self.grid_lines.append(line)

 def hide_grid(self):
 self.grid_on = False
 self.delete("grid")
 self.grid_lines = []

 def toggle_grid(self):
 if self.grid_on:
 self.hide_grid()
 else:
 self.show_grid()

 def redraw_shapes(self):
 self.delete("line")
 self.delete("calc")

 for shape_info in self.shapes:
 points = shape_info.get("points", [])
 if points:
 self.drawing_curve(points)

 def drawing_curve(self, points):
 for px, py in points:
 if 0 <= px <= self.winfo_width() and 0 <= py <= self.winfo_height():
 grid_x, grid_y, grid_x2, grid_y2 = self._get_grid_cell_coords(px, py)
 self.create_rectangle(grid_x, grid_y, grid_x2, grid_y2,
 fill="black", outline="darkgray", width=1,
 tags="line")

 if points == self.current_points:
 self.show_calculations(points, self.current_curve)

 def start_drawing(self, event):
 x, y = event.x, event.y
 if self.is_debug:
 x, y = self._snap_to_grid(x, y)

 self.start_x = x
 self.start_y = y

 def draw_shape(self, event):
 self.delete("preview")
 if self.start_x is None or self.start_y is None:
 return

 shape = self.current_curve
 x0, y0 = self.start_x, self.start_y
 x1, y1 = event.x, event.y

 if self.is_debug:
 x1, y1 = self._snap_to_grid(x1, y1)

 if not self.is_debug:
 if shape == "circle":
 radius = math.sqrt((x1 - x0) ** 2 + (y1 - y0) ** 2)
 self.create_oval(x0 - radius, y0 - radius, x0 + radius, y0 + radius,
 outline="gray", tags="preview", dash=(2, 2))
 elif shape == "ellipse":
 self.create_oval(x0, y0, x1, y1, outline="gray", tags="preview", dash=(2, 2))
 elif shape == "hyperbola":
 self.draw_hyperbola(x0, y0, x1, y1, preview=True)
 elif shape == "parabola":
 self.draw_parabola(x0, y0, x1, y1, preview=True)

 def finish_drawing(self, event):
 self.delete("preview")
 if self.start_x is None or self.start_y is None:
 return

 shape = self.current_curve
 x0, y0 = self.start_x, self.start_y
 x1, y1 = event.x, event.y

 if self.is_debug:
 x1, y1 = self._snap_to_grid(x1, y1)

 points_list = []

 if shape == "circle":
 radius = math.sqrt((x1 - x0) ** 2 + (y1 - y0) ** 2)
 if self.is_debug:
 points_list = self.calculate_circle_points(x0, y0, radius)
 else:
 self.create_oval(x0 - radius, y0 - radius, x0 + radius, y0 + radius,
 outline=self.line_color, width=1)

 elif shape == "ellipse":
 rx = abs(x1 - x0) // 2
 ry = abs(y1 - y0) // 2
 cx = (x0 + x1) // 2
 cy = (y0 + y1) // 2
 if self.is_debug:
 points_list = self.calculate_ellipse_points(cx, cy, rx, ry)
 else:
 self.create_oval(x0, y0, x1, y1, outline=self.line_color, width=1)

 elif shape == "hyperbola":
 points_list = self.calculate_hyperbola_points(x0, y0, x1, y1)

 elif shape == "parabola":
 points_list = self.calculate_parabola_points(x0, y0, x1, y1)

 if points_list:
 self.current_points = points_list
 self.drawing_curve(points_list)

 shape_info = {
 "type": shape,
 "points": points_list,
 "params": (x0, y0, x1, y1)
 }
 self.shapes.append(shape_info)

 self.start_x = None
 self.start_y = None

 def calculate_circle_points(self, cx, cy, radius):
 points = []
 x = 0
 y = int(radius)
 d = 3 - 2 * radius

 self.add_circle_symm_points(cx, cy, x, y, points)

 while y >= x:
 x += 1
 if d > 0:
 y -= 1
 d = d + 4 * (x - y) + 10
 else:
 d = d + 4 * x + 6
 self.add_circle_symm_points(cx, cy, x, y, points)

 return points

 def add_circle_symm_points(self, cx, cy, x, y, points):
 point_list = [
 (cx + x, cy + y), (cx - x, cy + y),
 (cx + x, cy - y), (cx - x, cy - y),
 (cx + y, cy + x), (cx - y, cy + x),
 (cx + y, cy - x), (cx - y, cy - x)
 ]

 for px, py in point_list:
 if 0 <= px <= self.winfo_width() and 0 <= py <= self.winfo_height():
 if (px, py) not in points:
 points.append((px, py))

 def calculate_ellipse_points(self, cx, cy, rx, ry):
 points = []
 x = 0
 y = ry
 rx_sqr = rx * rx
 ry_sqr = ry * ry

 d1 = ry_sqr - rx_sqr * ry + 0.25 * rx_sqr
 dx = 2 * ry_sqr * x
 dy = 2 * rx_sqr * y

 self.add_ellipse_symm_points(cx, cy, x, y, points)

 while dx < dy:
 x += 1
 dx += 2 * ry_sqr
 if d1 < 0:
 d1 += ry_sqr * (2 * x + 1)
 else:
 y -= 1
 dy -= 2 * rx_sqr
 d1 += ry_sqr * (2 * x + 1) - rx_sqr * 2 * y
 self.add_ellipse_symm_points(cx, cy, x, y, points)

 d2 = ry_sqr * (x + 0.5) ** 2 + rx_sqr * (y - 1) ** 2 - rx_sqr * ry_sqr

 while y > 0:
 y -= 1
 dy -= 2 * rx_sqr
 if d2 > 0:
 d2 += rx_sqr * (1 - 2 * y)
 else:
 x += 1
 dx += 2 * ry_sqr
 d2 += ry_sqr * (2 * x + 1) + rx_sqr * (1 - 2 * y)
 self.add_ellipse_symm_points(cx, cy, x, y, points)

 return points

 def add_ellipse_symm_points(self, cx, cy, x, y, points):
 point_list = [
 (cx + x, cy + y), (cx - x, cy + y),
 (cx + x, cy - y), (cx - x, cy - y)
 ]

 for px, py in point_list:
 if 0 <= px <= self.winfo_width() and 0 <= py <= self.winfo_height():
 if (px, py) not in points:
 points.append((px, py))

 def calculate_hyperbola_points(self, x0, y0, x1, y1):
 points = []
 a = max(abs(x1 - x0), self.cell_size)
 b = max(abs(y1 - y0) / 2, self.cell_size)
 cx = x0
 cy = y0

 max_range = min(abs(x1 - x0) * 2, 400)

 for x in range(-max_range, max_range + 1, self.cell_size):
 try:
 y = b * math.sqrt(1 + (x / a) ** 2)

 for sign in [1, -1]:
 px = cx + x
 py = cy + sign * y

 px = round(px / self.cell_size) * self.cell_size
 py = round(py / self.cell_size) * self.cell_size

 if 0 <= px <= self.winfo_width() and 0 <= py <= self.winfo_height():
 if (px, py) not in points:
 points.append((px, py))
 except (ValueError, OverflowError):
 continue

 return points

 def calculate_parabola_points(self, x0, y0, x1, y1):
 points = []
 p = max(abs(y1 - y0) / 2, self.cell_size)
 cx = x0
 cy = y0

 max_range = min(abs(x1 - x0) * 2, 400)

 for x in range(-max_range, max_range + 1, self.cell_size):
 try:
 y = (x ** 2) / (4 * p)

 px = cx + x
 py = cy + y

 px = round(px / self.cell_size) * self.cell_size
 py = round(py / self.cell_size) * self.cell_size

 if 0 <= px <= self.winfo_width() and 0 <= py <= self.winfo_height():
 if (px, py) not in points:
 points.append((px, py))
 except (ValueError, OverflowError):
 continue

 return points

 def draw_hyperbola(self, x0, y0, x1, y1, preview=False):
 if self.is_debug and not preview:
 points = self.calculate_hyperbola_points(x0, y0, x1, y1)
 self.drawing_curve(points)
 return []
 else:
 a = max(abs(x1 - x0), 1)
 b = max(abs(y1 - y0) / 2, 1)
 shape_ids = []

 for x in range(-a, a + 1):
 try:
 y = b * math.sqrt(1 + (x / a) ** 2)
 tag = "preview" if preview else None
 color = "gray" if preview else self.line_color

 oval1 = self.create_oval(x0 + x, y0 + y, x0 + x + 1, y0 + y + 1,
 outline=color, fill=color, tags=tag)
 oval2 = self.create_oval(x0 + x, y0 - y, x0 + x + 1, y0 - y + 1,
 outline=color, fill=color, tags=tag)

 if not preview:
 shape_ids.extend([oval1, oval2])
 except ValueError:
 continue
 return shape_ids

 def draw_parabola(self, x0, y0, x1, y1, preview=False):
 if self.is_debug and not preview:
 points = self.calculate_parabola_points(x0, y0, x1, y1)
 self.drawing_curve(points)
 return []
 else:
 p = max(abs(y1 - y0) / 2, 1)
 shape_ids = []

 for x in range(-abs(x1 - x0), abs(x1 - x0) + 1):
 try:
 y = (x ** 2) / (4 * p)
 tag = "preview" if preview else None
 color = "gray" if preview else self.line_color

 oval = self.create_oval(x0 + x, y0 + y, x0 + x + 1, y0 + y + 1,
 outline=color, fill=color, tags=tag)

 if not preview:
 shape_ids.append(oval)
 except ValueError:
 continue
 return shape_ids

 def show_calculations(self, points, curve_type):
 if not self.is_debug:
 return

 self.delete("calc")

 curve_names = {
 "circle": "ОКРУЖНОСТЬ",
 "ellipse": "ЭЛЛИПС",
 "hyperbola": "ГИПЕРБОЛА",
 "parabola": "ПАРАБОЛА"
 }

 calc_text = f"КРИВАЯ: {curve_names.get(curve_type, curve_type.upper())}\n"
 calc_text += f"ВСЕГО ТОЧЕК: {len(points)}\n\n"

 for i, (x, y) in enumerate(points[:5]):
 calc_text += f" {i+1}: ({x}, {y})\n"

 if len(points) > 5:
 calc_text += " ...\n"
 start_idx = max(5, len(points) - 5)
 for i, (x, y) in enumerate(points[-5:]):
 idx = len(points) - 5 + i
 calc_text += f" {idx+1}: ({x}, {y})\n"

 if curve_type == "circle" and len(points) > 0:
 cx = points[0][0]
 cy = points[0][1]
 radius = math.sqrt((points[0][0] - cx) ** 2 + (points[0][1] - cy) ** 2)
 calc_text += f"\nПАРАМЕТРЫ:\n"
 calc_text += f" Центр: ({cx}, {cy})\n"

 elif curve_type == "ellipse" and len(points) > 0:
 cx = points[0][0]
 cy = points[0][1]
 rx = abs(points[0][0] - cx)
 ry = abs(points[0][1] - cy)
 calc_text += f"\nПАРАМЕТРЫ:\n"
 calc_text += f" Центр: ({cx}, {cy})\n"
 calc_text += f" rx: {rx}, ry: {ry}\n"

 width = self.winfo_width()
 height = self.winfo_height()

 self.create_text(width - 10, height - 10,
 text=calc_text,
 anchor=tk.SE,
 font=("Courier", 9),
 fill="black",
 justify=tk.LEFT,
 tags="calc")

 def set_curve(self, curve):
 self.current_curve = curve

 def clear(self):
 self.delete("all")
 self.shapes = []
 self.current_points = []
 self.delete("calc")

 if self.is_debug and self.grid_on:
 self.show_grid()

 def set_parameters(self, radius, radius2, param):
 pass

Вывод: в результате выполнения данной лабораторной работы были получены основные навыки построения линий второго порядка. Также были изучены алгоритмы построения круга, эллипса, параболы и гиперболы.

Цель работы: 
Освоить принципы разработки прикладных сервисных программ для решения задачи анализа текста естественного языка. Вариант 5 – загрузка через DOCX.
Задачи лабораторной работы: 
1. Познакомиться с назначением, структурой и функциональностью, предоставляемой базовым ЛП для решения задачи автоматического синтаксического анализа ТЕЯ. 
2. Закрепить навыки программирования при решении задач автоматической обработки ТЕЯ. 
Используемые библиотеки
FastAPI – фреймворк для создания веб-приложений, обеспечивающий высокую производительность и автоматическую документацию.
SQLAlchemy – ORM для взаимодействия с реляционными базами данных, позволяет работать с таблицами через объекты, упрощая хранение и извлечение данных.
spaCy – библиотека для продвинутой обработки естественного языка. Используется для токенизации, определения частей речи, построения дерева зависимостей (модель ru_core_news_sm).
NLTK – библиотека для обработки естественного языка, применяется для построения дерева составляющих на основе простой грамматики.
pymorphy3 – морфологический анализатор для русского языка (используется для предыдущих лабораторных работ, не является основным для синтаксиса).
pdfplumber, python-docx, striprtf – библиотеки для извлечения текста из PDF, DOCX и RTF соответственно.
Jinja2 – шаблонизатор для генерации HTML-страниц на сервере, обеспечивает динамическое наполнение интерфейса.
Bootstrap – CSS-фреймворк, обеспечивающий адаптивный и удобный внешний вид веб-интерфейса.
Chardet – библиотека для автоматического определения кодировки текстовых файлов.
Интерфейс
Приложение представляет собой веб-сервис с пятью основными вкладками:
Загрузка – выбор файла (поддерживаемые форматы: TXT, PDF, DOCX, RTF), указание метаданных, морфологическая разметка.
Документы – просмотр, редактирование и удаление загруженных документов.
Конкорданс – поиск по словоформе или лемме с выводом контекста и экспортом в CSV.
Статистика – частотные списки словоформ, лемм, частей речи с фильтрацией по документу и экспортом.
Синтаксический анализ – новая вкладка, в которой пользователь может:
загрузить файл (TXT, PDF, DOCX, RTF) или ввести текст вручную;
указать диапазон предложений (с какого по какое);
выполнить синтаксический анализ;
просмотреть список зависимостей (главное → зависимое : тип связи) с возможностью экспорта в CSV;
просмотреть таблицу токенов с леммами, POS и зависимостями для выбранных предложений;
визуализировать дерево зависимостей (SVG) для первого предложения;
визуализировать дерево составляющих (PNG) для первого предложения.
