import json
from fastapi import FastAPI, Request, Depends, HTTPException
from fastapi.responses import HTMLResponse, JSONResponse, Response
from sqlalchemy.orm import Session
from datetime import datetime
from typing import List

from database import get_db, HistoryEntry
from models import Message, MessageCreate, MessageEdit, ChatHistory
from rest import Medical

app = FastAPI(title="Medical Chatbot")

# Инициализация
rest = Medical("knowledge_base.json")

@app.get("/favicon.ico")
async def favicon():
 return Response(status_code=204)

@app.get("/", response_class=HTMLResponse)
async def root(request: Request):
 with open("templates/index.html", "r", encoding="utf-8") as f:
 return HTMLResponse(content=f.read())

@app.get("/help", response_class=JSONResponse)
async def get_help():
 help_text = (
 "Медицинский помощник отвечает на вопросы о симптомах, лечении, первой помощи, "
 "профилактике и нормах показателей. Внимание: система не заменяет врача!"
 )
 return {"help": help_text}

@app.post("/chat", response_model=Message)
async def chat(message: MessageCreate, db: Session = Depends(get_db)):
 # Сохраняем вопрос пользователя
 user_msg = HistoryEntry(role="user", text=message.text, timestamp=datetime.now())
 db.add(user_msg)
 db.commit()
 db.refresh(user_msg)

 # Получаем ответ
 answer_text = rest.get_answer(message.text)

 # Сохраняем ответ системы
 system_msg = HistoryEntry(role="system", text=answer_text, timestamp=datetime.now())
 db.add(system_msg)
 db.commit()
 db.refresh(system_msg)

 return Message(role="system", text=answer_text, timestamp=system_msg.timestamp)

@app.get("/history", response_model=ChatHistory)
async def get_history(db: Session = Depends(get_db)):
 entries = db.query(HistoryEntry).order_by(HistoryEntry.timestamp).all()
 messages = [Message(role=e.role, text=e.text, timestamp=e.timestamp) for e in entries]
 return ChatHistory(messages=messages)

@app.delete("/history", response_model=dict)
async def clear_history(db: Session = Depends(get_db)):
 db.query(HistoryEntry).delete()
 db.commit()
 return {"status": "ok", "message": "История очищена"}

@app.put("/history/{message_id}", response_model=dict)
async def edit_message(message_id: int, edit: MessageEdit, db: Session = Depends(get_db)):
 entry = db.query(HistoryEntry).filter(HistoryEntry.id == message_id).first()
 if not entry:
 raise HTTPException(status_code=404, detail="Сообщение не найдено")
 entry.text = edit.new_text
 db.commit()
 return {"status": "ok", "message": f"Сообщение {message_id} изменено"}

@app.get("/history_with_ids", response_model=List[dict])
async def get_history_with_ids(db: Session = Depends(get_db)):
 entries = db.query(HistoryEntry).order_by(HistoryEntry.timestamp).all()
 return [{"id": e.id, "role": e.role, "text": e.text, "timestamp": e.timestamp.isoformat()} for e in entries]
