 async function editMessage() {
 const res = await fetch('/history_with_ids');
 const items = await res.json();
 if (!items.length) {
 alert('Нет сообщений для редактирования');
 return;
 }
 let listStr = items.map(m => `${m.id}: [${m.role}] ${m.text.substring(0,60)}...`).join('\n');
 const idStr = prompt('Введите ID сообщения для редактирования:\n' + listStr);
 if (!idStr) return;
 const id = parseInt(idStr);
 const item = items.find(m => m.id === id);
 if (!item) {
 alert('ID не найден');
 return;
 }
 const newText = prompt('Новый текст:', item.text);
 if (newText && newText !== item.text) {
 const putRes = await fetch(`/history/${id}`, {
 method: 'PUT',
 headers: { 'Content-Type': 'application/json' },
 body: JSON.stringify({ new_text: newText })
 });
 if (putRes.ok) {
 loadHistory();
 } else {
 alert('Ошибка редактирования');
 }
 }
 }

